import React, { useEffect, useState } from 'react';
import {
  Box, Typography, Grid, Paper,
  Dialog, DialogTitle, DialogContent, DialogActions,
  TextField, Button, CircularProgress, Alert, Snackbar,
  InputAdornment, IconButton
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import { Visibility, VisibilityOff } from '@mui/icons-material';
import { useAuth } from './AuthContext';

const CompanyProfiles = () => {
  const { user } = useAuth();
  const [companies, setCompanies] = useState([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [selectedCompany, setSelectedCompany] = useState(null);
  const [editMode, setEditMode] = useState(false);
  const [companyForm, setCompanyForm] = useState({
    name: '',
    address: '',
    phoneNumber: ''
  });
  const [loading, setLoading] = useState(true);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  // Password verification states
  const [passwordDialog, setPasswordDialog] = useState(false);
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [passwordError, setPasswordError] = useState('');
  const [verifyingPassword, setVerifyingPassword] = useState(false);
  const [pendingAction, setPendingAction] = useState(null);

  useEffect(() => {
    fetchCompanies();
  }, []);

  const fetchCompanies = async () => {
    try {
      setLoading(true);
      const response = await fetch('http://localhost:8080/companies/all');
      if (!response.ok) throw new Error('Failed to fetch companies');
      const data = await response.json();

      // Sort companies alphabetically by name
      const sortedCompanies = data.sort((a, b) => a.name.localeCompare(b.name));
      setCompanies(sortedCompanies);
    } catch (err) {
      console.error('Error fetching companies:', err);
      showSnackbarMessage('Error loading companies', 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleOpenAddDialog = () => {
    setCompanyForm({ name: '', address: '', phoneNumber: '' });
    setEditMode(false);
    setOpenDialog(true);
  };

  const handleOpenViewDialog = (company) => {
    setSelectedCompany(company);
    setCompanyForm({
      name: company.name,
      address: company.address,
      phoneNumber: company.phoneNumber
    });
    setEditMode(false);
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setSelectedCompany(null);
    setCompanyForm({ name: '', address: '', phoneNumber: '' });
    setEditMode(false);
  };

  const handleFormChange = (e) => {
    const { name, value } = e.target;
    setCompanyForm((prev) => ({ ...prev, [name]: value }));
  };

  const handlePasswordChange = (e) => {
    setPassword(e.target.value);
    if (passwordError) setPasswordError('');
  };

  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
  };

  const showSnackbarMessage = (message, severity = 'success') => {
    setSnackbar({
      open: true,
      message,
      severity
    });
  };

  const handleCloseSnackbar = () => {
    setSnackbar({
      ...snackbar,
      open: false
    });
  };

  const handleSave = async () => {
    // Validate form
    if (!companyForm.name || !companyForm.address || !companyForm.phoneNumber) {
      showSnackbarMessage('Please fill in all fields', 'error');
      return;
    }

    try {
      const response = await fetch('http://localhost:8080/companies/add', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(companyForm),
      });

      if (!response.ok) throw new Error('Failed to add company');

      handleCloseDialog();
      fetchCompanies();
      showSnackbarMessage('Company added successfully');
    } catch (err) {
      console.error('Error saving company:', err);
      showSnackbarMessage('Error adding company', 'error');
    }
  };

  const requestPasswordVerification = (action) => {
    setPendingAction(action);
    setPassword('');
    setPasswordError('');
    setPasswordDialog(true);
  };

  const verifyPassword = async () => {
    if (!password) {
      setPasswordError('Please enter your password');
      return;
    }

    if (!user || !user.username) {
      showSnackbarMessage('User information is missing', 'error');
      return;
    }

    setVerifyingPassword(true);

    try {
      const response = await fetch('http://localhost:8080/worker/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          username: user.username, 
          password: password 
        }),
      });

      if (!response.ok) {
        setPasswordError('Incorrect password');
        setVerifyingPassword(false);
        return;
      }

      // Password verified, perform the pending action
      setPasswordDialog(false);
      setVerifyingPassword(false);

      if (pendingAction === 'edit') {
        setEditMode(true);
      } else if (pendingAction === 'update') {
        performUpdate();
      } else if (pendingAction === 'delete') {
        performDelete();
      }

      setPassword('');
      setPendingAction(null);

    } catch (err) {
      console.error('Error verifying password:', err);
      setPasswordError('Error verifying password. Please try again.');
      setVerifyingPassword(false);
    }
  };

  const performUpdate = async () => {
    try {
      const response = await fetch(`http://localhost:8080/companies/${selectedCompany.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(companyForm),
      });

      if (!response.ok) throw new Error('Failed to update company');

      handleCloseDialog();
      fetchCompanies();
      showSnackbarMessage('Company updated successfully');
    } catch (err) {
      console.error('Error updating company:', err);
      showSnackbarMessage('Error updating company', 'error');
    }
  };

  const performDelete = async () => {
    try {
      const response = await fetch(`http://localhost:8080/companies/${selectedCompany.id}`, {
        method: 'DELETE',
      });

      if (!response.ok) throw new Error('Failed to delete company');

      handleCloseDialog();
      fetchCompanies();
      showSnackbarMessage('Company deleted successfully');
    } catch (err) {
      console.error('Error deleting company:', err);
      showSnackbarMessage('Error deleting company', 'error');
    }
  };

  const handleRequestEdit = () => {
    requestPasswordVerification('edit');
  };

  const handleRequestUpdate = () => {
    requestPasswordVerification('update');
  };

  const handleRequestDelete = () => {
    requestPasswordVerification('delete');
  };

  const handleClosePasswordDialog = () => {
    setPasswordDialog(false);
    setPassword('');
    setPasswordError('');
    setPendingAction(null);
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" align="center" gutterBottom sx={{ fontWeight: 'bold', mb: 4 }}>
        Company Profiles
      </Typography>

      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
          <CircularProgress />
        </Box>
      ) : (
        <Grid container spacing={2}>
          {companies.map((company) => (
            <Grid item xs={12} sm={6} md={4} lg={2} key={company.id}>
              <Paper
                elevation={3}
                sx={{ 
                  p: 2, 
                  textAlign: 'center', 
                  cursor: 'pointer',
                  height: '100%',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  '&:hover': { backgroundColor: '#f0f0f0' }
                }}
                onClick={() => handleOpenViewDialog(company)}
              >
                <Typography>{company.name}</Typography>
              </Paper>
            </Grid>
          ))}
          <Grid item xs={12} sm={6} md={4} lg={2}>
            <Paper
              elevation={3}
              sx={{ 
                p: 2, 
                textAlign: 'center', 
                cursor: 'pointer',
                height: '100%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                '&:hover': { backgroundColor: '#f0f0f0' }
              }}
              onClick={handleOpenAddDialog}
            >
              <AddIcon fontSize="large" />
            </Paper>
          </Grid>
        </Grid>
      )}

      {/* Company Dialog */}
      <Dialog open={openDialog} onClose={handleCloseDialog}>
        <DialogTitle>
          {selectedCompany ? (editMode ? "Edit Company" : "Company Details") : "Add New Company"}
        </DialogTitle>
        <DialogContent>
          <TextField
            label="Company Name"
            name="name"
            value={companyForm.name}
            onChange={handleFormChange}
            fullWidth
            margin="dense"
            disabled={!editMode && selectedCompany}
            required
          />
          <TextField
            label="Address"
            name="address"
            value={companyForm.address}
            onChange={handleFormChange}
            fullWidth
            margin="dense"
            disabled={!editMode && selectedCompany}
            required
          />
          <TextField
            label="Phone Number"
            name="phoneNumber"
            value={companyForm.phoneNumber}
            onChange={handleFormChange}
            fullWidth
            margin="dense"
            disabled={!editMode && selectedCompany}
            required
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog} sx={{ color: 'blue', textDecoration: 'underline' }}>
            Cancel
          </Button>
          {selectedCompany && !editMode && (
            <>
              <Button onClick={handleRequestEdit} sx={{ color: 'blue', textDecoration: 'underline' }}>
                Edit
              </Button>
              <Button onClick={handleRequestDelete} sx={{ color: 'blue', textDecoration: 'underline' }}>
                Delete
              </Button>
            </>
          )}
          {editMode && selectedCompany && (
            <Button onClick={handleRequestUpdate} variant="contained" color="primary">
              Save Changes
            </Button>
          )}
          {!selectedCompany && (
            <Button onClick={handleSave} variant="contained" color="primary">
              Save
            </Button>
          )}
        </DialogActions>
      </Dialog>

      {/* Password Verification Dialog */}
      <Dialog open={passwordDialog} onClose={handleClosePasswordDialog}>
        <DialogTitle>Password Verification</DialogTitle>
        <DialogContent>
          <Typography sx={{ mb: 2 }}>
            Please enter your password to {pendingAction === 'edit' ? 'edit' : 
                                         pendingAction === 'update' ? 'update' : 
                                         pendingAction === 'delete' ? 'delete' : 
                                         'perform this action on'} the company.
          </Typography>
          <TextField
            autoFocus
            margin="dense"
            label="Password"
            type={showPassword ? 'text' : 'password'}
            fullWidth
            value={password}
            onChange={handlePasswordChange}
            error={!!passwordError}
            helperText={passwordError}
            InputProps={{
              endAdornment: (
                <InputAdornment position="end">
                  <IconButton
                    aria-label="toggle password visibility"
                    onClick={togglePasswordVisibility}
                    edge="end"
                  >
                    {showPassword ? <VisibilityOff /> : <Visibility />}
                  </IconButton>
                </InputAdornment>
              ),
            }}
            onKeyPress={(e) => {
              if (e.key === 'Enter') {
                verifyPassword();
              }
            }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClosePasswordDialog} sx={{ color: 'blue', textDecoration: 'underline' }}>
            Cancel
          </Button>
          <Button 
            onClick={verifyPassword} 
            variant="contained" 
            color="primary"
            disabled={verifyingPassword}
          >
            {verifyingPassword ? <CircularProgress size={24} /> : 'Verify'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={5000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert 
          onClose={handleCloseSnackbar} 
          severity={snackbar.severity} 
          sx={{ width: '100%' }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default CompanyProfiles;
